Given a 2D integer matrix mat[][] of size n x m, where every row and column is sorted in increasing order and a number x, return true if the element x is present in the matrix. Otherwise, return false.Examples: Input: x = 62, mat[][] = [[3, 30, 38], [20, 52, 54], [35, 60, 69]]Output: falseExplanation: 62 is not present in the matrix.Input: x = 55, mat[][] = [[18, 21, 27], [38, 55, 67]]Output: trueExplanation: mat[1][1] is equal to 55.Input: x = 35, mat[][] = [[3, 30, 38], [20, 52, 54], [35, 60, 69]]Output: trueExplanation: mat[2][0] is equal to 35.Try It YourselfTable of Content[Naive Approach] Comparing with all elements - O(n*m) Time and O(1) Space[Better Approach] Binary Search - O(n*logm) Time and O(1) Space[Expected Approach] Eliminating rows or columns - O(n + m) Time and O(1) Space[Naive Approach] Comparing with all elements - O(n*m) Time and O(1) SpaceThe simple idea is to traverse the complete matrix and search for the target element. If the target element is found, return true. Otherwise, return false.
            C++

    #include <iostream>
#include <vector>

using namespace std;

bool matSearch(vector<vector<int>> &mat, int x) {
    int n = mat.size(), m = mat[0].size();

    // Iterate over all the elements to find x
	for(int i = 0; i < n; i++) {
    	for(int j = 0; j < m; j++) {
        	if(mat[i][j] == x)
                return true;
        }
    }

    // If x was not found, return false
    return false;
}

int main() {
    vector<vector<int>> mat = {{3, 30, 38},
                               {20, 52, 54},
                               {35, 60, 69}};
    int x = 35;
    if(matSearch(mat, x)) 
        cout << "true";
    else 
        cout << "false";
    return 0;
}


